mapper.select:
select from order_item where order_no in
#{orderNo}
order by id

select order_no as orderNo, count(1) as itemCount, coalesce(sum(qty), 0) as totalQty from order_item where order_no in
#{orderNo}
group by order_no

select i.product_id as productId, coalesce(sum(i.qty), 0) as quantity from order_item i join orders o on o.order_no = i.order_no where o.deleted = 0 and o.status in (20, 30, 40, 60) and o.paid_at is not null and o.paid_at >= #{start} and o.paid_at < #{end} and i.product_id in
#{productId}
group by i.product_id
